.h-5 { height: 20px; }
.w-8 { width: 32px; }
.w-10 { width: 40px; }
.h-10 { height: 40px; }
.w-12 { width: 48px; }
.h-12 { height: 48px; }
.w-\[1px\] { width: 1px; }
